  ('7c21b23b-7d1c-4abc-937b-9a9a2bd2a8c6', $$Economie$$, $$VWO$$, $$Phillipscurve richtsnoer voor beleid$$, $$VWO Economie 2017-I$$),
  ('b6722f23-f5d6-4fbe-8781-344bb64b1e80', $$Economie$$, $$VWO$$, $$Financiële blessuretijd voor BVV$$, $$VWO Economie 2017-I$$),
  ('4ce1ea52-7ab7-4f48-af35-78ce0dc2c3cc', $$Economie$$, $$VWO$$, $$Hypotheekrente in Hoogland: een onnodig hoge prijs?$$, $$VWO Economie 2017-I$$),
