   $$economie-vwo-2017-i-quichote-vraag1.png$$, $$2p 1 Bereken vanaf welke hoogte van de prijs van elektriciteit per kWh winst wordt gemaakt op de productie van het windmolenpark door Quichote.$$, array['bc47de80-e41b-4e83-b68b-93fbd6b9c079', '7aa5ab7e-5e8b-429b-a11a-74336d53a1c8']::uuid[]),
