   $$economie-vwo-2017-i-quichote-vraag3.png$$, $$2p 3 Leg uit dat in deze situatie een principaal-agentprobleem kan optreden.$$, array['7aa5ab7e-5e8b-429b-a11a-74336d53a1c8', '7650426c-b637-4ebe-959c-a5eac244cf75', 'cfbca1f6-38f6-449b-96ed-e314f870f234']::uuid[]),
