   '["Phillipscurve", "krappe arbeidsmarkt", "loonstijging", "inflatie", "werkloosheid"]'::jsonb,
   $$Via de arbeidsmarkt verklaren waarom de kortetermijn-Phillipscurve dalend verloopt.$$,
   $$economie-vwo-2017-i-phillipscurve-richtsnoer-voor-beleid-vraag5.png$$, $$2p 5 Verklaar via de arbeidsmarkt het dalende verloop van de Phillipscurve op korte termijn.$$, array['d409cd76-e275-4322-9879-a623e99de6f0', '3e8ce01f-69ca-44b4-b733-e25a14a8d0e8', '24872c3f-0c39-4e26-b885-33d242530093']::uuid[]),
