   $$economie-vwo-2017-i-phillipscurve-richtsnoer-voor-beleid-vraag8.png$$, $$2p 8 Verklaar bewering I.$$, array['3e8ce01f-69ca-44b4-b733-e25a14a8d0e8', '24872c3f-0c39-4e26-b885-33d242530093', '47399102-e416-42e3-bf81-b0332dffa74d']::uuid[]),
